// ShelfCheck cover overrides.
// covers-manifest.js is the AUTOMATED baseline, regenerated by tools/fetch-covers.mjs from IGDB.
// This file is for CURATOR-APPROVED corrections/additions only, and always wins over the
// generated manifest. Keep it small — it is not a replacement for the generator.
//
// Add entries as: "<census id>": "<image url>"  (identity covers)
// or:            "<product key>": "<image url>"  (collection/product covers, matches p.key
//                 from DATA.p / findProduct(), same keys used in SHELFCHECK_PRODUCT_COVERS)
//
// Empty maps are expected and fine — no manual corrections have been made yet.
(()=>{
  const COVER_OVERRIDES = {};
  const PRODUCT_COVER_OVERRIDES = {};
  window.SHELFCHECK_COVER_OVERRIDES = COVER_OVERRIDES;
  window.SHELFCHECK_PRODUCT_COVER_OVERRIDES = PRODUCT_COVER_OVERRIDES;
  // Merge overrides on top of the generated manifest here (rather than in cover-art-v080.js)
  // so the override always wins regardless of load order between this file and the manifest,
  // and so cover-art-v080.js doesn't need to know overrides exist.
  window.SHELFCHECK_COVERS = {...(window.SHELFCHECK_COVERS||{}), ...COVER_OVERRIDES};
  window.SHELFCHECK_PRODUCT_COVERS = {...(window.SHELFCHECK_PRODUCT_COVERS||{}), ...PRODUCT_COVER_OVERRIDES};
})();
